package LinkedSpec::BridgeBaseline;
use strict; use warnings;
BEGIN {
 require File::Basename; require File::Spec;
 my $base=File::Spec->rel2abs(File::Basename::dirname(File::Basename::dirname(__FILE__)));
 my @modules=qw(LinkedSpec/BindingRuntime.pm LinkedSpec/ActionIR/MethodLowering.pm LinkedSpec/CodeblockRuntime.pm);
 # Dependency BEGIN blocks prepend their own source root. Bind every selected
 # module's canonical key before loading absolute, committed copies.
 $INC{$_}=File::Spec->catfile($base,split('/',$_)) for @modules;
 for my $module (@modules) { require $INC{$module} }
 die 'baseline loaded current origin provider' if LinkedSpec::CodeblockRuntime->can('_codeblock_origin');
 for my $module (@modules) { die "baseline module mismatch: $module" unless index($INC{$module},$base)==0 }
}
